"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Cookie } from "@/components/ui/icons";

// Cookie Banner: generated by UIX from the design system. Same variants and sizes as the Figma component.

const cookieBannerVariants = cva(
  "flex bg-surface text-fg-primary border border-line-default rounded-xl",
  {
    variants: {
      layout: {
        bar: "w-full flex-row items-center border-t px-6 py-4 gap-4 [&_[data-slot=actions]]:flex-row-reverse",
        card: "w-[360px] max-w-full flex-col items-start p-5 gap-4 shadow-lg [&_[data-slot=actions]]:w-full [&_[data-slot=actions]]:flex-col [&_[data-slot=actions]>*]:justify-center",
      },
    },
    defaultVariants: {
      layout: "bar",
    },
  },
);

export interface CookieBannerProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "title">,
    VariantProps<typeof cookieBannerVariants> {
  title?: React.ReactNode;
  /** Replaces the cookie icon. */
  icon?: React.ReactNode;
  acceptLabel?: React.ReactNode;
  rejectLabel?: React.ReactNode;
  settingsLabel?: React.ReactNode;
  onAccept?: () => void;
  onReject?: () => void;
  onSettings?: () => void;
}

const CookieBanner = React.forwardRef<HTMLElement, CookieBannerProps>(
  ({ className, layout, title = "We use cookies", icon, acceptLabel = "Accept all", rejectLabel = "Reject all", settingsLabel = "Cookie settings", onAccept, onReject, onSettings, children, ...props }, ref) => {
    const titleId = React.useId();
    return (
      <section data-slot="cookie-banner" data-kind="surface" ref={ref} aria-labelledby={titleId} className={cn(cookieBannerVariants({ layout }), className)} {...props}>
        <span aria-hidden className="inline-flex shrink-0 items-center justify-center rounded-full size-10 bg-brand-subtle text-icon-brand [&_svg]:size-5">{icon ?? <Cookie />}</span>
        <div className="flex min-w-0 flex-1 flex-col gap-0-5">
          <h2 id={titleId} className="text-label-large text-fg-primary">{title}</h2>
          <p className="text-body-small text-fg-secondary">{children}</p>
        </div>
        <div data-slot="actions" className="flex shrink-0 items-center gap-3">
          <button type="button" onClick={onAccept} className="inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap transition-colors disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md h-10 px-4 gap-2 text-label-medium bg-brand text-fg-on-brand hover:bg-brand-hover active:bg-brand-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid">
            {acceptLabel}
          </button>
          <button type="button" onClick={onReject} className="inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap transition-colors disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md h-10 px-4 gap-2 text-label-medium border border-line-default bg-surface text-fg-primary hover:bg-subtle hover:border-line-strong active:bg-muted disabled:bg-disabled disabled:text-fg-disabled">
            {rejectLabel}
          </button>
          <button type="button" onClick={onSettings} className="inline-flex cursor-pointer items-center underline underline-offset-4 text-label-medium text-fg-brand rounded-xs focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
            {settingsLabel}
          </button>
        </div>
      </section>
    );
  },
);
CookieBanner.displayName = "CookieBanner";

export { CookieBanner, cookieBannerVariants };
